# src/lib/__tests__/seguridad-tracecat-conector.test.ts
  it("valida destinos correctos e incorrectos", () => {
    // Válido https
    const r1 = validarDestino("https://tracecat.example.com/webhook");
    expect(r1.ok).toBe(true);
    if (r1.ok) expect(r1.url.hostname).toBe("tracecat.example.com");

    // http sin permitirRedLocal -> rechaza
    const r2 = validarDestino("http://localhost:8080/hook");
    expect(r2.ok).toBe(false);

    // http con permitirRedLocal en localhost / 127.0.0.1 / *.local -> acepta
    const r3 = validarDestino("http://localhost:8080/hook", { permitirRedLocal: true });
    expect(r3.ok).toBe(true);

    const r4 = validarDestino("http://127.0.0.1/hook", { permitirRedLocal: true });
    expect(r4.ok).toBe(true);

    const r5 = validarDestino("http://mi-nodo.local/hook", { permitirRedLocal: true });
    expect(r5.ok).toBe(true);

    // http con dominio externo -> rechaza aun con permitirRedLocal
    const r6 = validarDestino("http://example.com/hook", { permitirRedLocal: true });
    expect(r6.ok).toBe(false);

    // URL con credenciales -> rechaza
    const r7 = validarDestino("https://user:pass@tracecat.example.com/hook");
    expect(r7.ok).toBe(false);

    // URL con fragmento -> rechaza
    const r8 = validarDestino("https://tracecat.example.com/hook#frag");
    expect(r8.ok).toBe(false);

    // URL enorme (>2048 chars) -> rechaza
    const urlLarga = "https://example.com/" + "a".repeat(2100);
    const r9 = validarDestino(urlLarga);
    expect(r9.ok).toBe(false);

    // URL vacía o inválida -> rechaza
    expect(validarDestino("").ok).toBe(false);
    expect(validarDestino("no-es-url").ok).toBe(false);
  });

