  it("firma el cuerpo correctamente y es reproducible", async () => {
    const cuerpo = '{"hola":"mundo"}';
    const f1 = await firmarCuerpo(cuerpo, secretoValido, ahora);
    const f2 = await firmarCuerpo(cuerpo, secretoValido, ahora);

    expect(f1.marca).toBe(f2.marca);
    expect(f1.firma).toBe(f2.firma);
    expect(typeof f1.firma).toBe("string");
    expect(f1.firma.length).toBe(64); // SHA-256 hex tiene 64 chars

    // Cambia al cambiar un byte del cuerpo
    const f3 = await firmarCuerpo('{"hola":"mund0"}', secretoValido, ahora);
    expect(f3.firma).not.toBe(f1.firma);

    // Cambia al cambiar la marca (otro ahora)
    const f4 = await firmarCuerpo(cuerpo, secretoValido, ahora + 5000);
    expect(f4.marca).not.toBe(f1.marca);
    expect(f4.firma).not.toBe(f1.firma);
  });

